-- Word 档案册对应的校园猫咪档案：按姓名、活动区域和图片逐条同步。
START TRANSACTION;

UPDATE animal SET name='COS、大寇', area='七公寓楼下', description='一只很有故事感的校园小猫，毛色清爽，喜欢在七公寓楼下晒太阳。熟悉后会轻轻蹭腿，是温柔又有分寸的小伙伴。', cover_image='/mock/animals/doc-cats/cat-01.png' WHERE animal_no='A-CAT-0001';
UPDATE animal SET name='踏雪', area='七公寓楼下', description='踏雪的爪爪像踩过一层薄雪，安静时像一枚小雪团。它喜欢在熟悉的角落观察路人，得到呼唤后会慢慢靠近。', cover_image='/mock/animals/doc-cats/cat-02.png' WHERE animal_no='A-CAT-0002';
UPDATE animal SET name='虎子', area='明学楼附近', description='虎子外表有一点小威风，性格却十分憨厚。它常在明学楼附近散步，看到熟悉的投喂人会开心地摇尾巴似的摆动尾巴。', cover_image='/mock/animals/doc-cats/cat-03.png' WHERE animal_no='A-CAT-0003';
UPDATE animal SET name='小小', area='七公寓楼下', description='小小身形轻巧，叫声细细的，胆子却比想象中大。它喜欢在七公寓楼下巡逻，偶尔用一双圆眼睛认真检查每一份猫粮。', cover_image='/mock/animals/doc-cats/cat-04.png' WHERE animal_no='A-CAT-0004';
UPDATE animal SET name='大橘', area='五公寓附近', description='大橘是一只阳光感满满的橘色小猫，亲人又贪吃。它最喜欢在五公寓附近等待投喂，吃饱后会找一块暖和的地方打盹。', cover_image='/mock/animals/doc-cats/cat-05.png' WHERE animal_no='A-CAT-0005';
UPDATE animal SET name='妹宝', area='七公寓楼下', description='妹宝长着一张甜甜的脸，性格软乎乎的。它在七公寓楼下很有自己的小路线，遇到温柔的呼唤会抬头回应。', cover_image='/mock/animals/doc-cats/cat-06.png' WHERE animal_no='A-CAT-0006';


